def transform(grid):
    width = len(grid[0])
    mid = width // 2
    half = mid
    right_start = mid + 1
    left_colors = {v for row in grid for v in row[:half]}
    right_colors = {v for row in grid for v in row[right_start:]}
    common = left_colors & right_colors
    background = next(iter(common)) if common else Counter(
